<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Composition with Red, Blue and Yellow (1930) | Piet Mondrian</title>
<meta name="description" content="The story of Piet Mondrian's Composition with Red, Blue and Yellow, 1930: the painter, the De Stijl movement and why the work matters.">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Jost:wght@400;500;700&display=swap" rel="stylesheet">
<style>
:root{
  --red:#d21f1b; --blue:#0f3f95; --yellow:#f6d21b;
  --white:#f7f5ee; --grey:#d9d8d2; --black:#111;
  --line:clamp(8px,1.3vw,16px);
}
*{box-sizing:border-box;margin:0}
html{scroll-behavior:smooth}
body{font-family:"Jost","Century Gothic","Futura",Arial,sans-serif;background:var(--black);color:var(--black);font-size:clamp(1rem,.95rem + .3vw,1.2rem);line-height:1.5}
a{color:inherit}
a:focus-visible{outline:4px solid var(--blue);outline-offset:3px}
.cell{background:var(--white);padding:clamp(14px,2.4vw,36px);min-width:0}
.red{background:var(--red);color:#fff}
.blue{background:var(--blue);color:#fff}
.yellow{background:var(--yellow)}
.grey{background:var(--grey)}
.label{font-size:.8em;font-weight:700;letter-spacing:.18em;text-transform:uppercase}

/* hero: the composition itself */
.hero{display:grid;gap:var(--line);padding:var(--line);min-height:100vh;min-height:100svh;
  grid-template-columns:minmax(40px,1fr) 3.4fr minmax(28px,.5fr);
  grid-template-rows:1.1fr 1.7fr auto}
.hero .a{grid-column:1;grid-row:1}
.hero .b{grid-column:1;grid-row:2}
.hero .red{grid-column:2/4;grid-row:1/3;display:flex;flex-direction:column;justify-content:flex-end}
.hero .blue{grid-column:1;grid-row:3}
.hero .c{grid-column:2;grid-row:3;display:flex;flex-wrap:wrap;gap:1em 2em;align-items:center;justify-content:space-between}
.hero .y{grid-column:3;grid-row:3;display:grid;grid-template-rows:1fr 1fr;gap:var(--line);background:var(--black);padding:0}
.hero .y i{background:var(--white)} .hero .y i+i{background:var(--yellow)}
h1{font-size:clamp(2.1rem,7.2vw,6.6rem);line-height:.98;font-weight:700;letter-spacing:-.02em;margin:.25em 0 .2em;text-wrap:balance}
.hero .red p.by{font-size:clamp(1.05rem,2vw,1.6rem);font-weight:500}
.hero .c p{max-width:34em;flex:1 1 16em}
.btn{display:inline-block;background:var(--black);color:#fff;text-decoration:none;font-weight:700;padding:.8em 1.2em;letter-spacing:.04em;border:0;transition:background .15s}
.btn:hover{background:var(--blue)}

/* facts */
.facts{display:grid;gap:var(--line);padding:0 var(--line) var(--line);grid-template-columns:repeat(6,1fr)}
.facts .cell{grid-column:span 2}
.facts .wide{grid-column:span 4}
.facts .full{grid-column:1/-1}
h2{font-size:clamp(1.5rem,3.4vw,2.8rem);line-height:1.05;font-weight:700;margin:.3em 0 .4em;text-wrap:balance}
.big{font-size:clamp(2.4rem,6vw,5rem);font-weight:700;line-height:1;margin:.15em 0}
.cell p+p{margin-top:.7em}
.cell p{max-width:38em}
.rules{list-style:none;padding:0;display:grid;gap:.6em;margin-top:.8em}
.rules li{display:flex;gap:.8em;align-items:center}
.sw{flex:none;display:inline-flex;gap:4px}
.sw b{width:1.1em;height:1.1em;border:3px solid var(--black);display:block}
.hv{width:1.1em;height:1.1em;flex:none;border-left:4px solid var(--black);border-bottom:4px solid var(--black)}
.cta{display:flex;flex-wrap:wrap;gap:1em 2em;align-items:center;justify-content:space-between}
.cta .btn{background:#fff;color:var(--black)} .cta .btn:hover{background:var(--yellow)}
footer{color:#ddd;padding:1em var(--line) 2em;font-size:.85em}
@media (max-width:760px){
  .facts .cell,.facts .wide{grid-column:1/-1}
  .hero .a,.hero .b,.hero .blue{padding:0}
}
@media (prefers-reduced-motion:reduce){html{scroll-behavior:auto}.btn{transition:none}}
</style>
</head>
